import sys

def solve(n, k):
    if k == 0:
        return "YES", n
    if k < 4:
        return "NO"
    if k % 4 != 0:
        return "NO"
    m = k // 4
    if m > n:
        return "NO"
    return "YES", n - m

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2
        result = solve(n, k)
        results.append(result)

    for result in results:
        print(result[0], result[1])

if __name__ == "__main__":
    main()
